import type { StaadVersion } from "../../types";

/**
 * STAAD.Pro version adapters
 * ==========================
 * The moving-load and static-load grammar implemented here is shared by the 2022
 * and 2025 adapters. No grammar difference between the two releases has been
 * verified by the authors of this application, and none is assumed: the adapters
 * exist so that a version-specific difference can be introduced in one place once
 * it has been demonstrated against a real installation.
 *
 * IMPORTANT: files generated by this application have NOT been executed inside a
 * licensed STAAD.Pro 2022 or 2025 installation as part of this build. The adapters
 * therefore carry the status "unverified" and the interface reports it wherever
 * output is produced. Do not claim compatibility for production use until the
 * release-gate tests in the project README have been run.
 */

export interface GrammarFeature {
  supported: boolean;
  note: string;
}

export interface StaadAdapter {
  version: StaadVersion;
  label: string;
  status: "unverified" | "verified";
  statusNote: string;
  movingLoadDefinition: GrammarFeature;
  loadGeneration: GrammarFeature;
  widthParameter: GrammarFeature;
  jointLoad: GrammarFeature;
  titleLimit: number;
  source: string;
}

const SHARED_STATUS =
  "Grammar shared with the other adapter. No verified grammar difference is known; output has not been executed in a STAAD.Pro installation.";

const base: Omit<StaadAdapter, "version" | "label"> = {
  status: "unverified",
  statusNote:
    "Generated files are syntax-checked by this application only. Run the release-gate tests in a licensed installation before relying on them.",
  movingLoadDefinition: {
    supported: true,
    note: "DEFINE MOVING LOAD / TYPE n LOAD … DISTANCE … [WIDTH …]",
  },
  loadGeneration: {
    supported: true,
    note: "LOAD GENERATION n / TYPE t x y z XINC|ZINC increment",
  },
  widthParameter: {
    supported: true,
    note: "WIDTH is emitted only for the 'axle load over width' and tracked-vehicle representations. It is not a substitute for arbitrary wheel coordinates.",
  },
  jointLoad: {
    supported: true,
    note: "JOINT LOAD with FX/FY/FZ components on listed joints.",
  },
  titleLimit: 24,
  source: "STAAD.Pro command reference (DEFINE MOVING LOAD, LOAD GENERATION, LOAD, JOINT LOAD).",
};

export const ADAPTERS: Record<StaadVersion, StaadAdapter> = {
  "2022": {
    ...base,
    version: "2022",
    label: "STAAD.Pro 2022",
  },
  "2025": {
    ...base,
    version: "2025",
    label: "STAAD.Pro 2025",
  },
};

export function getAdapter(version: StaadVersion): StaadAdapter {
  return ADAPTERS[version] ?? ADAPTERS["2022"];
}

export const SHARED_GRAMMAR_NOTE = SHARED_STATUS;
